    var GD = _t.GD, GM = _t.GM, GL = _t.GL, GP = _t.GP, GOLD = _t.GOLD, GOLDD = _t.GOLDD, CREAM = _t.CREAM, EXTRA = _t.EXTRA, INK = "#1c1c1e", MUT = "#6b7280";
    var emoji = ins.emoji || "📘", title = ins.title || "Unit Study";
