      var rows = dayTasks.map(function (t) { var cls = luPillType(t.title) === "pill-screen" ? " sched-screen" : ""; return '<div class="sched-row' + cls + '">' + String(t.title || "").split(" — ")[0] + '</div>\n'; }).join("");
