          <svg viewBox="0 0 36 36" width="34" height="34"><path d="M18,29 Q9,22 8,15 Q7,7 18,10 Q29,7 28,15 Q27,22 18,29Z" fill="white" stroke="#f472b6" stroke-width="3"/></svg>
